with valid_departments as (select * from departments where location = 'Tokyo' or budget between 1272000 and 2263000), summary as (select case when budget >= 3724000 then 'high' when budget >= 1109000 then 'mid' else 'low' end as budget_bucket, location, round((100 * sum(case when dept_name = 'Marketing' then 1 else 0 end)) / count(*), 1) as pct_marketing, sort_array(collect_set(location)) as location_list from valid_departments group by case when budget >= 3724000 then 'high' when budget >= 1109000 then 'mid' else 'low' end, location) select budget_bucket, location, pct_marketing, location_list from summary order by budget_bucket desc, location limit 10;
